module adder_pipe_64bit
    (
        input clk,
        input rst_n,
        input i_en,
        input [63:0] adda,
        input [63:0] addb,
        output [64:0] result,
        output reg o_en
    );

    reg [15:0] adda_reg1;
    reg [15:0] adda_reg2;
    reg [15:0] adda_reg3;
    reg [15:0] adda_reg4;

    reg [15:0] addb_reg1;
    reg [15:0] addb_reg2;
    reg [15:0] addb_reg3;
    reg [15:0] addb_reg4;

    reg [15:0] add_sum1;
    reg [15:0] add_sum2;
    reg [15:0] add_sum3;
    reg [15:0] add_sum4;

    reg i_en_reg1;
    reg i_en_reg2;
    reg i_en_reg3;
    reg i_en_reg4;

    assign add_sum1 = adda_reg1 + addb_reg1;
    assign add_sum2 = adda_reg2 + addb_reg2;
    assign add_sum3 = adda_reg3 + addb_reg3;
    assign add_sum4 = adda_reg4 + addb_reg4;

    assign result = {add_sum4, add_sum3, add_sum2, add_sum1};

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            adda_reg1 <= 'd0;
            adda_reg2 <= 'd0;
            adda_reg3 <= 'd0;
            adda_reg4 <= 'd0;
            addb_reg1 <= 'd0;
            addb_reg2 <= 'd0;
            addb_reg3 <= 'd0;
            addb_reg4 <= 'd0;
            i_en_reg1 <= 'd0;
            i_en_reg2 <= 'd0;
            i_en_reg3 <= 'd0;
            i_en_reg4 <= 'd0;
        end
        else begin
            adda_reg1 <= i_en ? adda[15:0] : 'd0;
            adda_reg2 <= i_en ? adda[31:16] : 'd0;
            adda_reg3 <= i_en ? adda[47:32] : 'd0;
            adda_reg4 <= i_en ? adda[63:48] : 'd0;
            addb_reg1 <= i_en ? addb[15:0] : 'd0;
            addb_reg2 <= i_en ? addb[31:16] : 'd0;
            addb_reg3 <= i_en ? addb[47:32] : 'd0;
            addb_reg4 <= i_en ? addb[63:48] : 'd0;
            i_en_reg1 <= i_en;
            i_en_reg2 <= i_en_reg1;
            i_en_reg3 <= i_en_reg2;
            i_en_reg4 <= i_en_reg3;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            o_en <= 'd0;
        end
        else begin
            o_en <= i_en_reg4;
        end
    end

endmodule

